let el=document.getElementById("tilt");const height=el.clientHeight,width=el.clientWidth;el.addEventListener("mousemove",handleMove);function handleMove(e){const t=e.layerX,n=e.layerY,s=20*((t-width/2)/width),o=-20*((n-height/2)/height),i="perspective(500px) scale(1.1) rotateX("+o+"deg) rotateY("+s+"deg)";el.style.transform=i}el.addEventListener("mouseout",function(){el.style.transform="perspective(500px) scale(1) rotateX(0) rotateY(0)"}),el.addEventListener("mousedown",function(){el.style.transform="perspective(500px) scale(0.9) rotateX(0) rotateY(0)"}),el.addEventListener("mouseup",function(){el.style.transform="perspective(500px) scale(1.1) rotateX(0) rotateY(0)"})